-- FINANCIA Phase 2 — budget, assets, liabilities, business, evidence, market data and audit
-- Generated by: supabase migration new phase2_finance_domains_and_audit
-- All household data is private and RLS-scoped through the approved membership helper.

BEGIN;

-- ---------------------------------------------------------------------------
-- Budget and income allocation
-- ---------------------------------------------------------------------------

CREATE TABLE public.allocation_plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  plan_name text NOT NULL,
  effective_from date NOT NULL,
  effective_to date,
  is_active boolean NOT NULL DEFAULT true,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT allocation_plans_pair_unique UNIQUE (household_id, id),
  CONSTRAINT allocation_plans_effective_dates_check
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE INDEX allocation_plans_household_active_idx
  ON public.allocation_plans (household_id, is_active, effective_from DESC);

CREATE TABLE public.allocation_buckets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  plan_id uuid NOT NULL,
  bucket_name text NOT NULL,
  bucket_type text NOT NULL CHECK (
    bucket_type IN (
      'household_operating',
      'savings',
      'husband_allowance',
      'wife_allowance',
      'business_reserve',
      'custom'
    )
  ),
  owner_attribution text CHECK (
    owner_attribution IS NULL OR owner_attribution IN ('husband', 'wife', 'shared')
  ),
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT allocation_buckets_pair_unique UNIQUE (household_id, id),
  CONSTRAINT allocation_buckets_plan_name_unique UNIQUE (plan_id, bucket_name),
  CONSTRAINT allocation_buckets_plan_fk
    FOREIGN KEY (household_id, plan_id)
    REFERENCES public.allocation_plans (household_id, id)
    ON DELETE RESTRICT
);

CREATE TABLE public.allocation_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  plan_id uuid NOT NULL,
  bucket_id uuid NOT NULL,
  rule_method text NOT NULL CHECK (rule_method IN ('fixed_amount', 'percentage', 'manual')),
  fixed_amount numeric(20,2) CHECK (fixed_amount IS NULL OR fixed_amount >= 0),
  percentage_value numeric(7,4) CHECK (percentage_value IS NULL OR percentage_value BETWEEN 0 AND 100),
  priority integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT allocation_rules_pair_unique UNIQUE (household_id, id),
  CONSTRAINT allocation_rules_bucket_unique UNIQUE (plan_id, bucket_id),
  CONSTRAINT allocation_rules_plan_fk
    FOREIGN KEY (household_id, plan_id)
    REFERENCES public.allocation_plans (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT allocation_rules_bucket_fk
    FOREIGN KEY (household_id, bucket_id)
    REFERENCES public.allocation_buckets (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT allocation_rules_method_value_check CHECK (
    (rule_method = 'fixed_amount' AND fixed_amount IS NOT NULL AND percentage_value IS NULL)
    OR
    (rule_method = 'percentage' AND percentage_value IS NOT NULL AND fixed_amount IS NULL)
    OR
    (rule_method = 'manual' AND fixed_amount IS NULL AND percentage_value IS NULL)
  )
);

CREATE TABLE public.allocation_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  plan_id uuid NOT NULL,
  source_transaction_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'confirmed', 'cancelled')),
  source_amount numeric(20,2) NOT NULL CHECK (source_amount >= 0),
  unallocated_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (unallocated_amount >= 0),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  confirmed_by uuid REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  confirmed_at timestamptz,
  CONSTRAINT allocation_runs_pair_unique UNIQUE (household_id, id),
  CONSTRAINT allocation_runs_plan_fk
    FOREIGN KEY (household_id, plan_id)
    REFERENCES public.allocation_plans (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT allocation_runs_source_transaction_fk
    FOREIGN KEY (household_id, source_transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX allocation_runs_household_created_idx
  ON public.allocation_runs (household_id, created_at DESC);

CREATE TABLE public.allocation_run_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  allocation_run_id uuid NOT NULL,
  bucket_id uuid NOT NULL,
  allocated_amount numeric(20,2) NOT NULL CHECK (allocated_amount >= 0),
  rule_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT allocation_run_lines_pair_unique UNIQUE (household_id, id),
  CONSTRAINT allocation_run_lines_bucket_unique UNIQUE (allocation_run_id, bucket_id),
  CONSTRAINT allocation_run_lines_run_fk
    FOREIGN KEY (household_id, allocation_run_id)
    REFERENCES public.allocation_runs (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT allocation_run_lines_bucket_fk
    FOREIGN KEY (household_id, bucket_id)
    REFERENCES public.allocation_buckets (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX allocation_run_lines_run_idx
  ON public.allocation_run_lines (household_id, allocation_run_id);

CREATE TABLE public.budget_periods (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  period_start date NOT NULL,
  period_end date NOT NULL,
  period_name text NOT NULL,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'closed')),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT budget_periods_pair_unique UNIQUE (household_id, id),
  CONSTRAINT budget_periods_start_unique UNIQUE (household_id, period_start),
  CONSTRAINT budget_periods_dates_check CHECK (period_end >= period_start)
);

CREATE TABLE public.budget_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  budget_period_id uuid NOT NULL,
  category_id uuid NOT NULL,
  budget_amount numeric(20,2) NOT NULL CHECK (budget_amount >= 0),
  rollover_enabled boolean NOT NULL DEFAULT false,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT budget_lines_pair_unique UNIQUE (household_id, id),
  CONSTRAINT budget_lines_period_category_unique UNIQUE (budget_period_id, category_id),
  CONSTRAINT budget_lines_period_fk
    FOREIGN KEY (household_id, budget_period_id)
    REFERENCES public.budget_periods (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT budget_lines_category_fk
    FOREIGN KEY (household_id, category_id)
    REFERENCES public.transaction_categories (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX budget_lines_category_idx
  ON public.budget_lines (household_id, category_id);

CREATE TABLE public.savings_goals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  goal_name text NOT NULL,
  target_amount numeric(20,2) NOT NULL CHECK (target_amount > 0),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  target_date date,
  owner_attribution text NOT NULL CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  linked_financial_account_id uuid,
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'completed', 'paused', 'cancelled')),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT savings_goals_pair_unique UNIQUE (household_id, id),
  CONSTRAINT savings_goals_account_fk
    FOREIGN KEY (household_id, linked_financial_account_id)
    REFERENCES public.financial_accounts (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX savings_goals_household_status_idx
  ON public.savings_goals (household_id, status);

-- ---------------------------------------------------------------------------
-- Personal assets and valuations. Business stock is intentionally separate.
-- ---------------------------------------------------------------------------

CREATE TABLE public.assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  ledger_account_id uuid NOT NULL,
  asset_kind text NOT NULL CHECK (
    asset_kind IN ('gold', 'silver', 'vehicle', 'property', 'deposit', 'investment', 'other')
  ),
  asset_name text NOT NULL,
  owner_attribution text NOT NULL CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  quantity_unit text NOT NULL DEFAULT 'unit',
  weight_grams numeric(20,6) CHECK (weight_grams IS NULL OR weight_grams >= 0),
  acquired_at timestamptz,
  acquisition_cost numeric(20,2) NOT NULL DEFAULT 0 CHECK (acquisition_cost >= 0),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disposed', 'archived')),
  notes text,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT assets_pair_unique UNIQUE (household_id, id),
  CONSTRAINT assets_ledger_account_fk
    FOREIGN KEY (household_id, ledger_account_id)
    REFERENCES public.ledger_accounts (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX assets_household_owner_kind_idx
  ON public.assets (household_id, owner_attribution, asset_kind, status);

CREATE TABLE public.asset_movements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  asset_id uuid NOT NULL,
  transaction_id uuid,
  movement_type text NOT NULL CHECK (
    movement_type IN ('acquisition', 'disposal', 'addition', 'quantity_adjustment', 'transfer_owner')
  ),
  quantity_delta numeric(20,6) NOT NULL,
  cost_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (cost_amount >= 0),
  occurred_at timestamptz NOT NULL,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT asset_movements_pair_unique UNIQUE (household_id, id),
  CONSTRAINT asset_movements_asset_fk
    FOREIGN KEY (household_id, asset_id)
    REFERENCES public.assets (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT asset_movements_transaction_fk
    FOREIGN KEY (household_id, transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT asset_movements_quantity_sign_check CHECK (
    (movement_type IN ('acquisition', 'addition') AND quantity_delta > 0)
    OR (movement_type = 'disposal' AND quantity_delta < 0)
    OR (movement_type IN ('quantity_adjustment', 'transfer_owner') AND quantity_delta <> 0)
  )
);

CREATE INDEX asset_movements_asset_occurred_idx
  ON public.asset_movements (household_id, asset_id, occurred_at DESC);

CREATE TABLE public.asset_valuations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  asset_id uuid NOT NULL,
  valuation_at timestamptz NOT NULL,
  market_value numeric(20,2) NOT NULL CHECK (market_value >= 0),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  valuation_source text NOT NULL,
  unit_price numeric(20,4) CHECK (unit_price IS NULL OR unit_price >= 0),
  notes text,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT asset_valuations_pair_unique UNIQUE (household_id, id),
  CONSTRAINT asset_valuations_asset_fk
    FOREIGN KEY (household_id, asset_id)
    REFERENCES public.assets (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX asset_valuations_latest_idx
  ON public.asset_valuations (household_id, asset_id, valuation_at DESC);

-- ---------------------------------------------------------------------------
-- Liabilities and settlement schedule
-- ---------------------------------------------------------------------------

CREATE TABLE public.liabilities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  ledger_account_id uuid NOT NULL,
  liability_type text NOT NULL
    CHECK (liability_type IN ('paylater', 'installment', 'loan', 'personal_debt', 'other')),
  lender_name text NOT NULL,
  description text NOT NULL,
  owner_attribution text NOT NULL CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  incurred_at timestamptz NOT NULL,
  original_principal numeric(20,2) NOT NULL CHECK (original_principal >= 0),
  due_date date,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'settled', 'cancelled')),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT liabilities_pair_unique UNIQUE (household_id, id),
  CONSTRAINT liabilities_ledger_account_fk
    FOREIGN KEY (household_id, ledger_account_id)
    REFERENCES public.ledger_accounts (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX liabilities_household_due_idx
  ON public.liabilities (household_id, due_date)
  WHERE status = 'active';

CREATE TABLE public.liability_installments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  liability_id uuid NOT NULL,
  installment_number integer NOT NULL CHECK (installment_number > 0),
  due_date date NOT NULL,
  principal_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (principal_amount >= 0),
  interest_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (interest_amount >= 0),
  fee_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (fee_amount >= 0),
  status text NOT NULL DEFAULT 'upcoming'
    CHECK (status IN ('upcoming', 'partially_paid', 'paid', 'overdue', 'cancelled')),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT liability_installments_pair_unique UNIQUE (household_id, id),
  CONSTRAINT liability_installments_number_unique UNIQUE (liability_id, installment_number),
  CONSTRAINT liability_installments_liability_fk
    FOREIGN KEY (household_id, liability_id)
    REFERENCES public.liabilities (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX liability_installments_due_idx
  ON public.liability_installments (household_id, due_date, status);

CREATE TABLE public.liability_payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  liability_id uuid NOT NULL,
  installment_id uuid,
  transaction_id uuid NOT NULL UNIQUE,
  principal_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (principal_amount >= 0),
  interest_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (interest_amount >= 0),
  fee_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (fee_amount >= 0),
  paid_at timestamptz NOT NULL,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT liability_payments_pair_unique UNIQUE (household_id, id),
  CONSTRAINT liability_payments_liability_fk
    FOREIGN KEY (household_id, liability_id)
    REFERENCES public.liabilities (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT liability_payments_installment_fk
    FOREIGN KEY (household_id, installment_id)
    REFERENCES public.liability_installments (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT liability_payments_transaction_fk
    FOREIGN KEY (household_id, transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT liability_payments_positive_total_check
    CHECK (principal_amount + interest_amount + fee_amount > 0)
);

CREATE INDEX liability_payments_liability_paid_idx
  ON public.liability_payments (household_id, liability_id, paid_at DESC);

-- ---------------------------------------------------------------------------
-- Gold distribution business and inventory. No personal-asset linkage.
-- ---------------------------------------------------------------------------

CREATE TABLE public.businesses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_name text NOT NULL,
  business_type text NOT NULL DEFAULT 'gold_distribution',
  owner_attribution text NOT NULL CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  is_active boolean NOT NULL DEFAULT true,
  notes text,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT businesses_pair_unique UNIQUE (household_id, id)
);

CREATE INDEX businesses_household_active_idx
  ON public.businesses (household_id, is_active);

CREATE TABLE public.business_products (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_id uuid NOT NULL,
  sku text,
  product_name text NOT NULL,
  product_kind text,
  quantity_unit text NOT NULL DEFAULT 'piece',
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT business_products_pair_unique UNIQUE (household_id, id),
  CONSTRAINT business_products_business_sku_unique UNIQUE (business_id, sku),
  CONSTRAINT business_products_business_fk
    FOREIGN KEY (household_id, business_id)
    REFERENCES public.businesses (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT business_products_business_product_unique UNIQUE (household_id, business_id, id)
);

CREATE INDEX business_products_business_active_idx
  ON public.business_products (household_id, business_id, is_active);

CREATE TABLE public.business_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_id uuid NOT NULL,
  transaction_id uuid NOT NULL UNIQUE,
  document_type text NOT NULL CHECK (
    document_type IN ('purchase', 'sale', 'business_expense', 'owner_withdrawal', 'return', 'adjustment')
  ),
  document_number text,
  counterparty_name text,
  document_at timestamptz NOT NULL,
  notes text,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT business_documents_pair_unique UNIQUE (household_id, id),
  CONSTRAINT business_documents_business_document_unique UNIQUE (household_id, business_id, id),
  CONSTRAINT business_documents_business_fk
    FOREIGN KEY (household_id, business_id)
    REFERENCES public.businesses (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT business_documents_transaction_fk
    FOREIGN KEY (household_id, transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX business_documents_business_date_idx
  ON public.business_documents (household_id, business_id, document_at DESC);

CREATE TABLE public.business_document_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_id uuid NOT NULL,
  business_document_id uuid NOT NULL,
  product_id uuid,
  quantity numeric(20,6),
  unit_price numeric(20,4),
  line_total numeric(20,2) NOT NULL DEFAULT 0 CHECK (line_total >= 0),
  cost_of_goods_sold numeric(20,2) CHECK (cost_of_goods_sold IS NULL OR cost_of_goods_sold >= 0),
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT business_document_lines_pair_unique UNIQUE (household_id, id),
  CONSTRAINT business_document_lines_product_line_unique UNIQUE (household_id, business_id, product_id, id),
  CONSTRAINT business_document_lines_document_fk
    FOREIGN KEY (household_id, business_id, business_document_id)
    REFERENCES public.business_documents (household_id, business_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT business_document_lines_product_fk
    FOREIGN KEY (household_id, business_id, product_id)
    REFERENCES public.business_products (household_id, business_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT business_document_lines_product_fields_check CHECK (
    (product_id IS NULL AND quantity IS NULL AND unit_price IS NULL)
    OR
    (product_id IS NOT NULL AND quantity IS NOT NULL AND quantity > 0
      AND unit_price IS NOT NULL AND unit_price >= 0)
  )
);

CREATE INDEX business_document_lines_document_idx
  ON public.business_document_lines (household_id, business_document_id);
CREATE INDEX business_document_lines_product_idx
  ON public.business_document_lines (household_id, business_id, product_id)
  WHERE product_id IS NOT NULL;

CREATE TABLE public.inventory_movements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_id uuid NOT NULL,
  product_id uuid NOT NULL,
  document_line_id uuid,
  movement_type text NOT NULL CHECK (
    movement_type IN ('purchase_in', 'sale_out', 'return_in', 'adjustment_in', 'adjustment_out')
  ),
  quantity_delta numeric(20,6) NOT NULL,
  unit_cost numeric(20,4) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  occurred_at timestamptz NOT NULL,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inventory_movements_pair_unique UNIQUE (household_id, id),
  CONSTRAINT inventory_movements_business_product_fk
    FOREIGN KEY (household_id, business_id, product_id)
    REFERENCES public.business_products (household_id, business_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT inventory_movements_document_line_fk
    FOREIGN KEY (household_id, business_id, product_id, document_line_id)
    REFERENCES public.business_document_lines (household_id, business_id, product_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT inventory_movements_quantity_sign_check CHECK (
    (movement_type IN ('purchase_in', 'return_in', 'adjustment_in') AND quantity_delta > 0)
    OR
    (movement_type IN ('sale_out', 'adjustment_out') AND quantity_delta < 0)
  ),
  CONSTRAINT inventory_movements_business_product_id_unique UNIQUE (household_id, business_id, product_id, id)
);

CREATE INDEX inventory_movements_product_date_idx
  ON public.inventory_movements (household_id, business_id, product_id, occurred_at);
CREATE INDEX inventory_movements_document_line_idx
  ON public.inventory_movements (household_id, document_line_id)
  WHERE document_line_id IS NOT NULL;

CREATE TABLE public.inventory_cost_allocations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  business_id uuid NOT NULL,
  product_id uuid NOT NULL,
  sale_document_line_id uuid NOT NULL,
  source_purchase_movement_id uuid NOT NULL,
  quantity_consumed numeric(20,6) NOT NULL CHECK (quantity_consumed > 0),
  unit_cost_snapshot numeric(20,4) NOT NULL CHECK (unit_cost_snapshot >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inventory_cost_allocations_pair_unique UNIQUE (household_id, id),
  CONSTRAINT inventory_cost_allocations_unique UNIQUE (sale_document_line_id, source_purchase_movement_id),
  CONSTRAINT inventory_cost_allocations_sale_line_fk
    FOREIGN KEY (household_id, business_id, product_id, sale_document_line_id)
    REFERENCES public.business_document_lines (household_id, business_id, product_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT inventory_cost_allocations_source_fk
    FOREIGN KEY (household_id, business_id, product_id, source_purchase_movement_id)
    REFERENCES public.inventory_movements (household_id, business_id, product_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX inventory_cost_allocations_sale_line_idx
  ON public.inventory_cost_allocations (household_id, sale_document_line_id);
CREATE INDEX inventory_cost_allocations_source_idx
  ON public.inventory_cost_allocations (household_id, source_purchase_movement_id);

-- ---------------------------------------------------------------------------
-- Private evidence, market observations, and append-only audit events
-- ---------------------------------------------------------------------------

CREATE TABLE public.receipts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  transaction_id uuid,
  storage_bucket text NOT NULL DEFAULT 'financia-private',
  storage_path text NOT NULL,
  original_filename text,
  mime_type text NOT NULL,
  file_size_bytes bigint NOT NULL CHECK (file_size_bytes > 0),
  sha256_hash text,
  uploaded_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  uploaded_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT receipts_pair_unique UNIQUE (household_id, id),
  CONSTRAINT receipts_path_unique UNIQUE (storage_bucket, storage_path),
  CONSTRAINT receipts_transaction_fk
    FOREIGN KEY (household_id, transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX receipts_transaction_idx
  ON public.receipts (household_id, transaction_id)
  WHERE transaction_id IS NOT NULL;
CREATE INDEX receipts_hash_idx
  ON public.receipts (household_id, sha256_hash)
  WHERE sha256_hash IS NOT NULL;

CREATE TABLE public.market_price_observations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  instrument_kind text NOT NULL CHECK (instrument_kind IN ('gold', 'silver')),
  product_name text,
  price_type text NOT NULL CHECK (price_type IN ('retail', 'buyback', 'spot')),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  unit_name text NOT NULL DEFAULT 'gram',
  price_per_unit numeric(20,4) NOT NULL CHECK (price_per_unit >= 0),
  source_name text NOT NULL,
  source_url text,
  observed_at timestamptz NOT NULL,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  raw_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT market_price_observations_pair_unique UNIQUE (household_id, id)
);

CREATE INDEX market_prices_latest_idx
  ON public.market_price_observations (
    household_id, instrument_kind, product_name, price_type, observed_at DESC
  );

CREATE TABLE public.audit_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  event_type text NOT NULL CHECK (event_type IN ('INSERT', 'UPDATE', 'DELETE')),
  entity_table text NOT NULL,
  entity_id uuid NOT NULL,
  before_data jsonb,
  after_data jsonb,
  request_id text,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT audit_events_pair_unique UNIQUE (household_id, id)
);

CREATE INDEX audit_events_household_time_idx
  ON public.audit_events (household_id, occurred_at DESC);
CREATE INDEX audit_events_entity_idx
  ON public.audit_events (entity_table, entity_id);

-- ---------------------------------------------------------------------------
-- Domain integrity triggers
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION private.guard_allocation_run()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_transaction_type text;
  v_transaction_status text;
  v_allocated numeric(20,2);
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT transaction_type, status
      INTO v_transaction_type, v_transaction_status
    FROM public.transactions
    WHERE household_id = NEW.household_id
      AND id = NEW.source_transaction_id;

    IF v_transaction_type IS DISTINCT FROM 'income'
       OR v_transaction_status IS DISTINCT FROM 'posted' THEN
      RAISE EXCEPTION 'Allocation runs require a posted income transaction';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status <> 'draft' THEN
    RAISE EXCEPTION 'Confirmed or cancelled allocation runs are immutable';
  END IF;

  IF NEW.household_id IS DISTINCT FROM OLD.household_id
     OR NEW.plan_id IS DISTINCT FROM OLD.plan_id
     OR NEW.source_transaction_id IS DISTINCT FROM OLD.source_transaction_id
     OR NEW.source_amount IS DISTINCT FROM OLD.source_amount THEN
    RAISE EXCEPTION 'Allocation run source and plan are immutable';
  END IF;

  IF NEW.status = 'confirmed' THEN
    SELECT COALESCE(sum(allocated_amount), 0)
      INTO v_allocated
    FROM public.allocation_run_lines
    WHERE household_id = NEW.household_id
      AND allocation_run_id = NEW.id;

    IF v_allocated + NEW.unallocated_amount <> NEW.source_amount THEN
      RAISE EXCEPTION 'Allocation lines plus unallocated amount must equal source amount';
    END IF;

    NEW.confirmed_at := now();
    NEW.confirmed_by := (SELECT auth.uid());
  ELSIF NEW.status = 'cancelled' THEN
    NEW.confirmed_at := NULL;
    NEW.confirmed_by := NULL;
  ELSIF NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'Invalid allocation run status transition';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_budget_line_category()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_category_type text;
BEGIN
  SELECT category_type INTO v_category_type
  FROM public.transaction_categories
  WHERE household_id = NEW.household_id
    AND id = NEW.category_id;

  IF v_category_type IS DISTINCT FROM 'expense' THEN
    RAISE EXCEPTION 'Budget lines must use an expense category';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_liability_payment()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_transaction_type text;
BEGIN
  SELECT transaction_type INTO v_transaction_type
  FROM public.transactions
  WHERE household_id = NEW.household_id
    AND id = NEW.transaction_id;

  IF v_transaction_type IS DISTINCT FROM 'liability_payment' THEN
    RAISE EXCEPTION 'Liability payment must reference a liability_payment transaction';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_business_document()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_transaction_type text;
BEGIN
  SELECT transaction_type INTO v_transaction_type
  FROM public.transactions
  WHERE household_id = NEW.household_id
    AND id = NEW.transaction_id;

  IF v_transaction_type IS NULL THEN
    RAISE EXCEPTION 'Business document transaction not found';
  END IF;

  IF NEW.document_type = 'purchase' AND v_transaction_type <> 'business_purchase' THEN
    RAISE EXCEPTION 'Purchase documents require business_purchase transactions';
  ELSIF NEW.document_type = 'sale' AND v_transaction_type <> 'business_sale' THEN
    RAISE EXCEPTION 'Sale documents require business_sale transactions';
  ELSIF NEW.document_type = 'business_expense' AND v_transaction_type <> 'business_expense' THEN
    RAISE EXCEPTION 'Expense documents require business_expense transactions';
  ELSIF NEW.document_type = 'owner_withdrawal' AND v_transaction_type <> 'owner_withdrawal' THEN
    RAISE EXCEPTION 'Withdrawal documents require owner_withdrawal transactions';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_business_document_line()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_document_type text;
  v_expected_total numeric(20,2);
BEGIN
  SELECT document_type INTO v_document_type
  FROM public.business_documents
  WHERE household_id = NEW.household_id
    AND business_id = NEW.business_id
    AND id = NEW.business_document_id;

  IF v_document_type IS NULL THEN
    RAISE EXCEPTION 'Business document not found';
  END IF;

  IF NEW.product_id IS NOT NULL THEN
    v_expected_total := round(NEW.quantity * NEW.unit_price, 2);
    IF NEW.line_total <> v_expected_total THEN
      RAISE EXCEPTION 'Business line total must equal quantity multiplied by unit price';
    END IF;
    IF v_document_type NOT IN ('purchase', 'sale', 'return', 'adjustment') THEN
      RAISE EXCEPTION 'This business document type does not accept product lines';
    END IF;
  ELSIF v_document_type NOT IN ('business_expense', 'owner_withdrawal', 'adjustment') THEN
    RAISE EXCEPTION 'Product is required for purchase, sale, and return lines';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_inventory_cost_allocation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_source_type text;
  v_source_quantity numeric(20,6);
  v_already_allocated numeric(20,6);
  v_sale_document_type text;
BEGIN
  SELECT movement_type, quantity_delta
    INTO v_source_type, v_source_quantity
  FROM public.inventory_movements
  WHERE household_id = NEW.household_id
    AND business_id = NEW.business_id
    AND product_id = NEW.product_id
    AND id = NEW.source_purchase_movement_id
  FOR UPDATE;

  IF v_source_type NOT IN ('purchase_in', 'return_in')
     OR v_source_quantity IS NULL OR v_source_quantity <= 0 THEN
    RAISE EXCEPTION 'FIFO source must be a positive purchase or return movement';
  END IF;

  SELECT bd.document_type
    INTO v_sale_document_type
  FROM public.business_document_lines AS bdl
  JOIN public.business_documents AS bd
    ON bd.household_id = bdl.household_id
   AND bd.business_id = bdl.business_id
   AND bd.id = bdl.business_document_id
  WHERE bdl.household_id = NEW.household_id
    AND bdl.business_id = NEW.business_id
    AND bdl.product_id = NEW.product_id
    AND bdl.id = NEW.sale_document_line_id;

  IF v_sale_document_type IS DISTINCT FROM 'sale' THEN
    RAISE EXCEPTION 'FIFO allocations must point to a sale document line';
  END IF;

  SELECT COALESCE(sum(quantity_consumed), 0)
    INTO v_already_allocated
  FROM public.inventory_cost_allocations
  WHERE household_id = NEW.household_id
    AND business_id = NEW.business_id
    AND product_id = NEW.product_id
    AND source_purchase_movement_id = NEW.source_purchase_movement_id
    AND id IS DISTINCT FROM NEW.id;

  IF v_already_allocated + NEW.quantity_consumed > v_source_quantity THEN
    RAISE EXCEPTION 'FIFO allocation exceeds available quantity in source lot';
  END IF;

  RETURN NEW;
END;
$function$;

-- Append-only audit trigger. It writes with its own narrowly scoped definer
-- privilege because authenticated users do not receive INSERT on audit_events.
CREATE OR REPLACE FUNCTION private.audit_row_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_row jsonb;
  v_before jsonb;
  v_after jsonb;
  v_household_id uuid;
  v_entity_id uuid;
  v_actor uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_row := to_jsonb(OLD);
    v_before := v_row;
    v_after := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_row := to_jsonb(NEW);
    v_before := to_jsonb(OLD);
    v_after := v_row;
  ELSE
    v_row := to_jsonb(NEW);
    v_before := NULL;
    v_after := v_row;
  END IF;

  v_household_id := (v_row ->> 'household_id')::uuid;
  v_entity_id := (v_row ->> 'id')::uuid;
  v_actor := (SELECT auth.uid());

  INSERT INTO public.audit_events (
    household_id,
    actor_user_id,
    event_type,
    entity_table,
    entity_id,
    before_data,
    after_data,
    request_id
  )
  VALUES (
    v_household_id,
    v_actor,
    TG_OP,
    TG_TABLE_NAME,
    v_entity_id,
    v_before,
    v_after,
    NULLIF(current_setting('request.headers', true)::jsonb ->> 'x-request-id', '')
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

-- Append-only protection for audit events.
CREATE OR REPLACE FUNCTION private.prevent_audit_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
BEGIN
  RAISE EXCEPTION 'Audit events are append-only';
END;
$function$;

CREATE TRIGGER allocation_runs_guard
BEFORE INSERT OR UPDATE ON public.allocation_runs
FOR EACH ROW EXECUTE FUNCTION private.guard_allocation_run();

CREATE TRIGGER budget_lines_guard_category
BEFORE INSERT OR UPDATE ON public.budget_lines
FOR EACH ROW EXECUTE FUNCTION private.guard_budget_line_category();

CREATE TRIGGER liability_payments_guard
BEFORE INSERT OR UPDATE ON public.liability_payments
FOR EACH ROW EXECUTE FUNCTION private.guard_liability_payment();

CREATE TRIGGER business_documents_guard
BEFORE INSERT OR UPDATE ON public.business_documents
FOR EACH ROW EXECUTE FUNCTION private.guard_business_document();

CREATE TRIGGER business_document_lines_guard
BEFORE INSERT OR UPDATE ON public.business_document_lines
FOR EACH ROW EXECUTE FUNCTION private.guard_business_document_line();

CREATE TRIGGER inventory_cost_allocations_guard
BEFORE INSERT OR UPDATE ON public.inventory_cost_allocations
FOR EACH ROW EXECUTE FUNCTION private.guard_inventory_cost_allocation();

CREATE TRIGGER audit_events_immutable
BEFORE UPDATE OR DELETE ON public.audit_events
FOR EACH ROW EXECUTE FUNCTION private.prevent_audit_mutation();

